    );
  }

  // ---- Erasure request methods ----

  async findErasureRequest(merchantId: string, requestId: string): Promise<Record<string, unknown> | undefined> {
    const result = await pool.query(
      `SELECT id, merchant_id, customer_id, status, attempts, last_error,
              created_at, updated_at, completed_at
       FROM customers.erasure_requests WHERE merchant_id=$1 AND id=$2`,
      [merchantId, requestId],
    );
    return result.rows[0] as Record<string, unknown> | undefined;
  }

  async findErasureRequestByCustomer(merchantId: string, customerId: string): Promise<Record<string, unknown> | undefined> {
    const result = await pool.query(
      `SELECT id, merchant_id, customer_id, status, attempts, last_error,
              created_at, updated_at, completed_at
       FROM customers.erasure_requests WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    return result.rows[0] as Record<string, unknown> | undefined;
  }

  async createErasureRequest(
    client: pg.PoolClient,
    merchantId: string,
    customerId: string,
  ): Promise<Record<string, unknown>> {
    const result = await client.query(
      `INSERT INTO customers.erasure_requests(merchant_id, customer_id)
       VALUES($1, $2)
       ON CONFLICT(merchant_id, customer_id) DO NOTHING
       RETURNING id, merchant_id, customer_id, status, attempts, last_error, created_at, updated_at, completed_at`,
      [merchantId, customerId],
    );
    return result.rows[0]!;
  }

  async updateErasureRequestStatus(
    client: pg.PoolClient,
    requestId: string,
    status: string,
    lastError?: string | null,
  ): Promise<void> {
    await client.query(
      `UPDATE customers.erasure_requests
       SET status=$2, updated_at=now(),
           completed_at=CASE WHEN $2='completed' THEN now() ELSE completed_at END,
           last_error=$3, attempts=CASE WHEN $2='processing' THEN attempts+1 ELSE attempts END
       WHERE id=$1`,
      [requestId, status, lastError ?? null],
    );
  }

  async clearCustomerPII(client: pg.PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `UPDATE customers.customers
       SET email='redacted-' || id || '@deleted.example.test',
           name='Deleted Customer',
           phone=NULL,
           external_reference='deleted-' || id,
           metadata='{}'::jsonb,
           status='deleted',
           updated_at=now()
       WHERE merchant_id=$1 AND id=$2`,
      [merchantId, customerId],
    );
  }

  async deleteCustomerAddresses(client: pg.PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `DELETE FROM customers.addresses WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
  }

  async deleteCustomerContacts(client: pg.PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `DELETE FROM customers.contacts WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
  }

  async deleteCustomerPaymentMethods(client: pg.PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `DELETE FROM customers.payment_method_refs WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
  }

  async deleteProviderCustomerMappings(client: pg.PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `DELETE FROM customers.provider_customer_mappings WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
  }

  async anonymizePaymentIntents(client: pg.PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `UPDATE payments.payment_intents
       SET customer_snapshot=jsonb_build_object('id', customer_snapshot->>'id', 'status', 'deleted'),
           updated_at=now()
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
  }

  async anonymizeRefunds(client: pg.PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `UPDATE payments.refunds
       SET customer_email=NULL
       WHERE merchant_id=$1 AND payment_intent_id IN (
         SELECT id FROM payments.payment_intents WHERE merchant_id=$1 AND customer_id=$2
       )`,
      [merchantId, customerId],
    );
  }

  async anonymizeInvoices(client: pg.PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `UPDATE payments.invoices
       SET billing_snapshot=jsonb_build_object('status', 'deleted')
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
  }

  async clearNotificationPreferences(client: pg.PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `DELETE FROM operations.notification_preferences WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
  }

  async anonymizeAnalyticsEvents(client: pg.PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `UPDATE operations.analytics_events
       SET email=NULL, anonymous_id='deleted-' || id::text, properties='{}'::jsonb
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
  }

  async anonymizeDocumentManifests(client: pg.PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `UPDATE operations.document_manifests
       SET customer_id=NULL, metadata=metadata - 'importId' - 'source'
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
  }

  async findCustomerImportKeys(merchantId: string): Promise<string[]> {
    const result = await pool.query<{ object_key: string }>(
      `SELECT object_key FROM customers.customer_imports WHERE merchant_id=$1`,
      [merchantId],
    );
    return result.rows.map((r) => r.object_key);
  }

  async ensureErasureRequestExists(
    client: pg.PoolClient,
    merchantId: string,
    customerId: string,
    requestId: string,
  ): Promise<Record<string, unknown>> {
    const result = await client.query(
      `INSERT INTO customers.erasure_requests(id, merchant_id, customer_id)
       VALUES($1, $2, $3)
       ON CONFLICT(merchant_id, customer_id) DO NOTHING
       RETURNING id, merchant_id, customer_id, status, attempts, last_error, created_at, updated_at, completed_at`,
      [requestId, merchantId, customerId],
    );
    return result.rows[0]!;
  }
}

