app.post('/v1/customer-imports', async (request, reply) => {
    const principal = await authenticate(request, 'customers:write');
    const input = importSchema.parse(request.body);
    const importId = await service.importCustomerArtifact(principal.merchantId, input.source, JSON.stringify(input.record));
    return reply.code(201).send({ id: importId });
  });

  // ---- Erasure request endpoints ----

  app.post('/v1/customers/:customerId/erasure-requests', async (request, reply) => {
    const principal = await authenticate(request, 'privacy:erase');
    const { customerId } = z.object({ customerId: z.string().uuid() }).parse(request.params);
    const idempotencyKey = request.headers['idempotency-key'];
    if (typeof idempotencyKey !== 'string' || idempotencyKey.length < 8 || idempotencyKey.length > 200) {
      return reply.code(400).send({ error: 'valid_idempotency_key_required' });
    }

    const customer = await repository.find(principal.merchantId, customerId);
    if (!customer) return reply.code(404).send({ error: 'customer_not_found' });

    const existingRequest = await repository.findErasureRequestByCustomer(principal.merchantId, customerId);
    if (existingRequest) {
      return reply.code(202).send({
        id: existingRequest.id,
        customerId: existingRequest.customer_id,
        status: existingRequest.status,
        attempts: existingRequest.attempts,
        createdAt: existingRequest.created_at,
        updatedAt: existingRequest.updated_at,
        completedAt: existingRequest.completed_at,
        lastError: existingRequest.last_error,
      });
    }

    const erasureRequest = await service.requestErasure(principal.merchantId, customerId);
    return reply.code(202).send({
      id: erasureRequest.id,
      customerId: erasureRequest.customer_id,
      status: erasureRequest.status,
      attempts: erasureRequest.attempts,
      createdAt: erasureRequest.created_at,
      updatedAt: erasureRequest.updated_at,
      completedAt: erasureRequest.completed_at,
      lastError: erasureRequest.last_error,
    });
  });

  app.get('/v1/erasure-requests/:requestId', async (request, reply) => {
    const principal = await authenticate(request, 'privacy:erase');
    const { requestId } = z.object({ requestId: z.string().uuid() }).parse(request.params);
    const erasureRequest = await service.getErasureRequest(principal.merchantId, requestId);
    if (!erasureRequest) return reply.code(404).send({ error: 'erasure_request_not_found' });
    return {
      id: erasureRequest.id,
      customerId: erasureRequest.customer_id,
      status: erasureRequest.status,
      attempts: erasureRequest.attempts,
      createdAt: erasureRequest.created_at,
      updatedAt: erasureRequest.updated_at,
      completedAt: erasureRequest.completed_at,
      lastError: erasureRequest.last_error,
    };
  });
}

